188:     static String resolveArmArchType() {
189:         if (System.getProperty("os.name").contains("Linux")) {
190:             String armType = getHardwareName();
191:             // armType (uname -m) can be armv5t, armv5te, armv5tej, armv5tejl, armv6, armv7, armv7l,
192:             // aarch64, i686
193: 
194:             // for Android, we fold everything that is not aarch64 into arm
195:             if (isAndroid()) {
196:                 if (armType.startsWith("aarch64")) {
197:                     // Use arm64
198:                     return "aarch64";
199:                 } else {
200:                     return "arm";
201:                 }
202:             }
203: 
204:             if (armType.startsWith("armv6")) {
205:                 // Raspberry PI
206:                 return "armv6";
207:             } else if (armType.startsWith("armv7")) {
208:                 // Generic
209:                 return "armv7";
210:             } else if (armType.startsWith("armv5")) {
211:                 // Use armv5, soft-float ABI
212:                 return "arm";
213:             } else if (armType.startsWith("aarch64")) {
214:                 boolean is32bitJVM = "32".equals(System.getProperty("sun.arch.data.model"));
215:                 if (is32bitJVM) {
216:                     // An aarch64 architecture should support armv7
217:                     return "armv7";
218:                 } else {
219:                     // Use arm64
220:                     return "aarch64";
221:                 }
222:             }
223: 
224:             // Java 1.8 introduces a system property to determine armel or armhf
225:             // https://bugs.openjdk.org/browse/JDK-8005545
226:             String abi = System.getProperty("sun.arch.abi");
227:             if (abi != null && abi.startsWith("gnueabihf")) {
228:                 return "armv7";
229:             }
230: 
231:             // For java7, we still need to run some shell commands to determine ABI of JVM
232:             String javaHome = System.getProperty("java.home");
233:             try {
234:                 // determine if first JVM found uses ARM hard-float ABI
235:                 int exitCode = Runtime.getRuntime().exec("which readelf").waitFor();
236:                 if (exitCode == 0) {
237:                     String[] cmdarray = {
238:                         "/bin/sh",
239:                         "-c",
240:                         "find '"
241:                                 + javaHome
242:                                 + "' -name 'libjvm.so' | head -1 | xargs readelf -A | "
243:                                 + "grep 'Tag_ABI_VFP_args: VFP registers'"
244:                     };
245:                     exitCode = Runtime.getRuntime().exec(cmdarray).waitFor();
246:                     if (exitCode == 0) {
247:                         return "armv7";
248:                     }
249:                 } else {
250:                     LogHolder.logger.warn(
251:                             () ->
252:                                     "readelf not found. Cannot check if running on an armhf system, armel architecture will be presumed");
253:                 }
254:             } catch (IOException | InterruptedException e) {
255:                 // ignored: fall back to "arm" arch (soft-float ABI)
256:             }
257:         }
258:         // Use armv5, soft-float ABI
259:         return "arm";
260:     }
