262:     public static String getArchName() {
263:         String override = System.getProperty("org.sqlite.osinfo.architecture");
264:         if (override != null) {
265:             return override;
266:         }
267: 
268:         String osArch = System.getProperty("os.arch");
269: 
270:         if (osArch.startsWith("arm")) {
271:             osArch = resolveArmArchType();
272:         } else {
273:             String lc = osArch.toLowerCase(Locale.US);
274:             if (archMapping.containsKey(lc)) return archMapping.get(lc);
275:         }
276:         return translateArchNameToFolderName(osArch);
277:     }
