279:     static String translateOSNameToFolderName(String osName) {
280:         if (osName.contains("Windows")) {
281:             return "Windows";
282:         } else if (osName.contains("Mac") || osName.contains("Darwin")) {
283:             return "Mac";
284:         } else if (osName.contains("AIX")) {
285:             return "AIX";
286:         } else if (isAndroid()) {
287:             return "Linux-Android";
288:         } else if (isMusl()) {
289:             return "Linux-Musl";
290:         } else if (osName.contains("Linux")) {
291:             return "Linux";
292:         } else {
293:             return osName.replaceAll("\\W", "");
294:         }
295:     }
296: 
297:     static String translateArchNameToFolderName(String archName) {
298:         return archName.replaceAll("\\W", "");
299:     }
