                URL finalVersionFile = versionFile;
                LoggerFactory.getLogger(VersionHolder.class)
                        .error(
                                () ->
                                        MessageFormat.format(
                                                "Could not read version from file: {0}",
                                                finalVersionFile),
                                e);
            }
            VERSION = version;
        }
    }
